function buildPgPoolConfig(connectionString) {
  const url = new URL(connectionString);
  const sslMode = (url.searchParams.get("sslmode") || process.env.PGSSLMODE || "").toLowerCase();
  const sslEnabled = !!sslMode && sslMode !== "disable";
  const baseConfig = {
    host: url.hostname,
    port: url.port ? parseInt(url.port, 10) : 5432,
    database: url.pathname?.startsWith("/") ? url.pathname.slice(1) : url.pathname,
    user: decodeURIComponent(url.username || ""),
    password: decodeURIComponent(url.password || "")
  };
  if (!sslEnabled) return baseConfig;
  const rejectUnauthorizedDefault = sslMode === "verify-full" || sslMode === "verify-ca";
  const rejectUnauthorized = (process.env.PG_SSL_REJECT_UNAUTHORIZED || String(rejectUnauthorizedDefault)).toLowerCase() === "true";
  return {
    ...baseConfig,
    ssl: {
      rejectUnauthorized
    }
  };
}
