router.post("/signup", async (req, res) => {
  try {
    const { email, password, name } = signupSchema.parse(req.body);
    const existingUser = await db.query.publicUsers.findFirst({
      where: and2(
        eq2(publicUsers.email, email.toLowerCase()),
        eq2(publicUsers.agentSlug, "default")
      )
    });
    if (existingUser) {
      if (existingUser.emailVerified) {
        return res.status(409).json({
          success: false,
          error: "An account with this email already exists. Please login instead."
        });
      } else {
        const verificationToken2 = generateVerificationToken();
        const tokenExpiry2 = new Date(Date.now() + 24 * 60 * 60 * 1e3);
        await db.update(publicUsers).set({
          verificationToken: verificationToken2,
          verificationTokenExpiry: tokenExpiry2,
          name: name || existingUser.name,
          password: await bcrypt2.hash(password, 10)
        }).where(eq2(publicUsers.id, existingUser.id));
        await sendVerificationEmail(email, name || existingUser.name || "there", verificationToken2);
        return res.status(200).json({
          success: true,
          message: "A new verification email has been sent. Please check your inbox.",
          requiresVerification: true
        });
      }
    }
    const hashedPassword = await bcrypt2.hash(password, 10);
    const verificationToken = generateVerificationToken();
    const tokenExpiry = new Date(Date.now() + 24 * 60 * 60 * 1e3);
    const [newUser] = await db.insert(publicUsers).values({
      email: email.toLowerCase(),
      name,
      password: hashedPassword,
      agentSlug: "default",
      emailVerified: false,
      verificationToken,
      verificationTokenExpiry: tokenExpiry
    }).returning();
    const emailSent = await sendVerificationEmail(email, name, verificationToken);
    if (!emailSent) {
      console.error("Failed to send verification email to:", email);
    }
    res.status(201).json({
      success: true,
      message: "Account created! Please check your email to verify your account.",
      requiresVerification: true,
      user: {
        id: newUser.id,
        email: newUser.email,
        name: newUser.name
      }
    });
  } catch (error) {
    console.error("Signup error:", error);
    if (error.name === "ZodError") {
      return res.status(400).json({
        success: false,
        error: "Validation failed",
        details: error.errors
      });
    }
    res.status(500).json({
      success: false,
      error: "Failed to create account. Please try again."
    });
  }
});
