  app2.post("/api/events/setup-omaha-sources", requireAuth, async (req, res) => {
    try {
      const userId2 = String(req.user?.id);
      const { eventIngestionService: eventIngestionService2 } = await Promise.resolve().then(() => (init_event_ingestion(), event_ingestion_exports));
      const templates = eventIngestionService2.getPopularOmahaCalendars();
      const realEstateTemplates = templates.filter(
        (t) => t.name.includes("Real Estate") || t.name.includes("Realtors") || t.name.includes("OABR")
      );
      const existingSources = await storage.getEventSources(userId2);
      const addedSources = [];
      for (const template of realEstateTemplates) {
        const alreadyExists = existingSources.some(
          (s) => s.name === template.name || s.config?.scrapeUrl === template.scrapeUrl
        );
        if (!alreadyExists) {
          const config = {};
          if (template.calendarId) config.calendarId = template.calendarId;
          if (template.icalUrl) config.icalUrl = template.icalUrl;
          if (template.scrapeUrl) config.scrapeUrl = template.scrapeUrl;
          if (template.scraperType) config.scraperType = template.scraperType;
          const source = await storage.createEventSource({
            userId: userId2,
            name: template.name,
            type: template.type,
            config,
            status: "active"
          });
          addedSources.push(source);
        }
      }
      if (addedSources.length > 0) {
        for (const source of addedSources) {
          await eventIngestionService2.syncSource(source);
        }
      }
      res.json({
        success: true,
        addedSources: addedSources.length,
        message: `Added ${addedSources.length} Omaha real estate event sources`
      });
    } catch (error) {
      console.error("Failed to setup Omaha sources:", error);
      res.status(500).json({ error: "Failed to setup Omaha sources" });
    }
  });
