  app2.post(
    "/api/photo-avatars/groups/:groupId/upload-looks",
    requireAuth,
    upload.array("photos", 4),
    // Max 4 photos per HeyGen API limit
    async (req, res) => {
      try {
        const { groupId } = req.params;
        const userId2 = String(req.user?.id);
        const { names } = req.body;
        if (!userId2) {
          return res.status(401).json({ error: "User not authenticated" });
        }
        const dbGroup = await storage.getPhotoAvatarGroupByHeygenIdAndUser(
          groupId,
          userId2
        );
        if (!dbGroup) {
          return res.status(404).json({ error: "Avatar group not found" });
        }
        const files = req.files;
        if (!files || files.length === 0) {
          return res.status(400).json({ error: "At least one photo is required" });
        }
        console.log(`\u{1F4F8} Uploading ${files.length} look photos for group ${groupId}`);
        const photoAvatarService = new HeyGenPhotoAvatarService();
        const uploadResults = [];
        let lookNames = [];
        if (names) {
          try {
            lookNames = typeof names === "string" ? JSON.parse(names) : names;
          } catch {
            lookNames = [];
          }
        }
        for (let i = 0; i < files.length; i++) {
          const file = files[i];
          const lookName = lookNames[i] || `Look ${i + 1}`;
          try {
            const fileBuffer = fs3.readFileSync(file.path);
            const imageKey = await photoAvatarService.uploadCustomPhoto(
              fileBuffer,
              file.mimetype || "image/jpeg"
            );
            await photoAvatarService.addLooks({
              groupId,
              imageKeys: [imageKey],
              name: lookName
            });
            uploadResults.push({
              imageKey,
              name: lookName,
              success: true
            });
            console.log(`\u2705 Uploaded and added look "${lookName}" with key: ${imageKey}`);
          } catch (error) {
            console.error(`Failed to upload look ${i + 1}:`, error);
            uploadResults.push({
              imageKey: "",
              name: lookName,
              success: false
            });
          } finally {
            try {
              fs3.unlinkSync(file.path);
            } catch {
            }
          }
        }
        const successCount = uploadResults.filter((r) => r.success).length;
        console.log(`\u{1F4F8} Look upload complete: ${successCount}/${files.length} successful`);
        res.json({
          success: successCount > 0,
          message: `Added ${successCount} of ${files.length} looks to avatar group`,
          results: uploadResults
        });
      } catch (error) {
        console.error("Failed to upload looks:", error);
        res.status(500).json({ error: "Failed to upload looks" });
      }
    }
  );
