  app2.post("/api/webhooks/heygen", async (req, res) => {
    try {
      const { event_type, event_data } = req.body;
      console.log("\u{1F4E8} HeyGen Webhook received:", event_type);
      const webhookSecret = process.env.HEYGEN_WEBHOOK_SECRET;
      const signature = req.headers["signature"];
      if (webhookSecret) {
        if (!signature) {
          console.warn("\u{1F512} Webhook rejected: Missing signature header");
          return res.status(401).json({ error: "Missing signature" });
        }
        const rawBody = req.rawBody;
        if (!rawBody) {
          console.warn("\u{1F512} Webhook rejected: Raw body not available");
          return res.status(500).json({ error: "Internal error" });
        }
        const computedSignature = crypto3.createHmac("sha256", webhookSecret).update(rawBody).digest("hex");
        const signatureBuffer = Buffer.from(signature, "hex");
        const computedBuffer = Buffer.from(computedSignature, "hex");
        if (signatureBuffer.length !== computedBuffer.length || !crypto3.timingSafeEqual(signatureBuffer, computedBuffer)) {
          console.warn("\u{1F512} Webhook rejected: Invalid signature");
          return res.status(401).json({ error: "Invalid signature" });
        }
        console.log("\u2705 Webhook signature verified");
      } else {
        console.warn("\u26A0\uFE0F HEYGEN_WEBHOOK_SECRET not configured - webhook verification disabled");
      }
      console.log("\u{1F4E8} Event data:", JSON.stringify(event_data, null, 2));
      if (event_type === "avatar_video.success") {
        const { video_id, url, callback_id } = event_data;
        const video = await storage.getVideoByHeygenId(video_id);
        if (video) {
          await storage.updateVideoContentWithUserGuard(video.id, video.userId, {
            status: "completed",
            videoUrl: url
          });
          realtimeService.notifyVideoGenerationComplete(
            parseInt(video.userId),
            video.id,
            url,
            video.title
          );
          console.log(`\u2705 Video ${video_id} marked as completed via webhook`);
        } else {
          console.warn(`\u26A0\uFE0F Video not found for HeyGen ID: ${video_id}`);
        }
      } else if (event_type === "avatar_video.fail") {
        const { video_id, msg, callback_id } = event_data;
        const video = await storage.getVideoByHeygenId(video_id);
        if (video) {
          await storage.updateVideoContentWithUserGuard(video.id, video.userId, {
            status: "failed",
            errorMessage: msg
          });
          realtimeService.notifyVideoGenerationFailed(
            parseInt(video.userId),
            video.id,
            msg,
            video.title
          );
          console.log(`\u274C Video ${video_id} marked as failed via webhook: ${msg}`);
        } else {
          console.warn(`\u26A0\uFE0F Video not found for HeyGen ID: ${video_id}`);
        }
      }
      res.status(200).json({ received: true });
    } catch (error) {
      console.error("\u274C Webhook processing error:", error);
      res.status(200).json({ received: true, error: "Processing failed" });
    }
  });
  app2.options("/api/webhooks/heygen", (req, res) => {
    res.status(200).send();
  });
