  app2.get("/api/videos/:videoId/status", requireAuth, async (req, res) => {
    try {
      const { videoId } = req.params;
      const userId2 = req.user?.id;
      console.log("\u{1F4CA} Backend: Getting video status for:", videoId);
      const heyGenService = new HeyGenService();
      const status = await heyGenService.getVideoStatus(videoId);
      console.log("\u2705 Backend: Video status result:", status);
      let response = { ...status };
      if (status.status === "completed" && status.video_url && userId2) {
        try {
          const allVideos = await storage.getVideoContent(String(userId2));
          const videoRecord = allVideos.find(
            (v) => v.metadata && typeof v.metadata === "object" && "heygenVideoId" in v.metadata && v.metadata.heygenVideoId === videoId
          );
          if (videoRecord) {
            await storage.updateVideoContent(videoRecord.id, {
              status: "ready",
              videoUrl: status.video_url,
              thumbnailUrl: status.thumbnail_url
            });
            console.log(
              "\u{1F4BE} Backend: Updated video record with HeyGen URLs:",
              videoRecord.id
            );
            try {
              console.log("\u{1F4BE} Backend: Attempting S3 backup...");
              const videoResponse = await fetch(status.video_url);
              if (videoResponse.ok) {
                const videoBuffer = Buffer.from(
                  await videoResponse.arrayBuffer()
                );
                const s3Service2 = new S3UploadService();
                const s3VideoUrl = await s3Service2.uploadFile(
                  userId2,
                  videoBuffer,
                  `generated-videos/${videoId}.mp4`,
                  "video/mp4"
                );
                console.log("\u2705 Backend: Video backed up to S3:", s3VideoUrl);
                response.s3_video_url = s3VideoUrl;
                let s3ThumbnailUrl = null;
                if (status.thumbnail_url) {
                  try {
                    const thumbnailResponse = await fetch(status.thumbnail_url);
                    if (thumbnailResponse.ok) {
                      const thumbnailBuffer = Buffer.from(
                        await thumbnailResponse.arrayBuffer()
                      );
                      s3ThumbnailUrl = await s3Service2.uploadFile(
                        userId2,
                        thumbnailBuffer,
                        `generated-videos/${videoId}_thumbnail.jpg`,
                        "image/jpeg"
                      );
                      response.s3_thumbnail_url = s3ThumbnailUrl;
                      console.log(
                        "\u2705 Backend: Thumbnail backed up to S3:",
                        s3ThumbnailUrl
                      );
                    }
                  } catch (thumbError) {
                    console.error(
                      "\u26A0\uFE0F Backend: Thumbnail backup failed:",
                      thumbError
                    );
                  }
                }
                await storage.updateVideoContent(videoRecord.id, {
                  videoUrl: s3VideoUrl,
                  thumbnailUrl: s3ThumbnailUrl || status.thumbnail_url
                });
                console.log(
                  "\u{1F4BE} Backend: Updated video record with S3 URLs:",
                  videoRecord.id
                );
              }
            } catch (backupError) {
              console.error(
                "\u26A0\uFE0F Backend: S3 backup failed, HeyGen URLs still available:",
                backupError
              );
            }
          }
        } catch (dbError) {
          console.error("\u26A0\uFE0F Backend: Database update failed:", dbError);
        }
      }
      res.json(response);
    } catch (error) {
      console.error("\u274C Backend: Failed to get video status");
      console.error("\u274C Backend: Error message:", error?.message);
      if (error?.status === 404) {
        console.log(
          "\u23F1\uFE0F Backend: Video not found in HeyGen status service yet, returning 'processing'"
        );
        return res.json({ video_id: req.params.videoId, status: "processing" });
      }
      res.status(500).json({
        error: "Failed to get video status",
        details: error?.message || String(error)
      });
    }
  });
