  app2.post("/api/track/generate-engagement-lead", async (req, res) => {
    try {
      const { sessionId, agentSlug } = req.body;
      if (!sessionId || !agentSlug) {
        return res.status(400).json({ error: "sessionId and agentSlug required" });
      }
      const {
        engagementLeads: engagementLeads2,
        userSessions: userSessions2,
        propertyInteractions: propertyInteractions2,
        propertyLikes: propertyLikes2
      } = await Promise.resolve().then(() => (init_schema(), schema_exports));
      const { eq: eq12, and: and4, sql: drizzleSql, desc: desc3 } = await import("drizzle-orm");
      const existingLead = await db.select().from(engagementLeads2).where(eq12(engagementLeads2.sessionId, sessionId)).limit(1);
      if (existingLead.length > 0) {
        return res.json({
          success: true,
          leadId: existingLead[0].id,
          alreadyExists: true
        });
      }
      const session = await db.select().from(userSessions2).where(eq12(userSessions2.sessionId, sessionId)).limit(1);
      if (session.length === 0) {
        return res.status(404).json({ error: "Session not found" });
      }
      const sessionData = session[0];
      let score = 0;
      if (sessionData.totalTimeSpentSeconds > 300) score += 20;
      if (sessionData.totalPropertiesViewed > 3) score += 15;
      if (sessionData.totalPropertiesLiked > 0)
        score += sessionData.totalPropertiesLiked * 10;
      const likedProps = await db.select().from(propertyLikes2).where(eq12(propertyLikes2.sessionId, sessionId));
      const likedPropertyIds = likedProps.map((p) => p.propertyId);
      let reason = "high_engagement";
      if (sessionData.totalPropertiesLiked >= 2)
        reason = "liked_multiple_properties";
      else if (sessionData.totalTimeSpentSeconds > 600)
        reason = "spent_long_time_on_site";
      else if (sessionData.totalPropertiesViewed > 5)
        reason = "viewed_many_properties";
      let quality = "warm";
      if (score >= 40) quality = "hot";
      else if (score < 25) quality = "cold";
      const lead = await db.insert(engagementLeads2).values({
        sessionId,
        agentSlug,
        engagementScore: score,
        engagementReason: reason,
        engagementDetails: {
          timeSpent: sessionData.totalTimeSpentSeconds,
          propertiesViewed: sessionData.totalPropertiesViewed,
          propertiesLiked: sessionData.totalPropertiesLiked
        },
        likedPropertyIds: likedPropertyIds.length > 0 ? likedPropertyIds : null,
        leadQuality: quality,
        leadStatus: "auto_generated",
        ipAddress: sessionData.ipAddress,
        userAgent: sessionData.userAgent
      }).returning();
      console.log(
        `\u2705 Generated ${quality} lead for session ${sessionId} (score: ${score})`
      );
      res.json({ success: true, leadId: lead[0].id, score, quality });
    } catch (error) {
      console.error("\u274C Error generating engagement lead:", error);
      res.status(500).json({ error: "Failed to generate lead" });
    }
  });
